const source=`function verify117(g) {
 const cols="ABCDEFGHJ", co=i=>cols[i%9]+(9-Math.floor(i/9)), idx=p=>(9-Number(p[1]))*9+cols.indexOf(p[0]);
 const ns=i=>[i%9?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(j=>j>=0);
 const parse=r=>{const t=r.content.filter(c=>c.type==="text").map(c=>c.text).join("\\n");const b=Array(81).fill(".");for(const l of t.split("\\n")){const m=l.match(/^\\s*([1-9])\\s+((?:[XO.]\\s+){8}[XO.])/);if(m)m[2].trim().split(/\\s+/).forEach((v,x)=>b[(9-Number(m[1]))*9+x]=v);}return{t,b,next:Number(t.match(/Move number: (\\d+)/)[1]),captures:(t.match(/Captured by Black: (\\d+); by White: (\\d+)/)||[]).slice(1).map(Number),ko:(t.match(/Ko point: ([^.]+)\\./)||[])[1]};};
 const group=(b,i)=>{const st=[i],seen=new Set([i]),libs=new Set();while(st.length){const j=st.pop();for(const k of ns(j)){if(b[k]===".")libs.add(k);else if(b[k]===b[i]&&!seen.has(k)){seen.add(k);st.push(k);}}}return{stones:[...seen],libs:[...libs]};};
 let b=Array(81).fill("."),caps=[0,0],ko="none",n=0;const hist=[{b:[...b],captures:[...caps],ko}],moves=[],ownStates=[];
 for(const a of g.actions){const t=parse(a.response).t;const wm=t.match(/Your opponent played ([A-HJ][1-9])/);const wp=/Your opponent passed\\./.test(t);if(!wm&&!wp)throw Error("Missing reply");
 for(const [color,p] of [["X",a.move],["O",wm?wm[1]:"pass"]]){const before=[...b];let removed=[];if(p!=="pass"){const i=idx(p);if(b[i]!==".")throw Error("Occupied "+p);if(ko===p)throw Error("Ko "+p);b[i]=color;for(const j of ns(i)){if(b[j]!=="."&&b[j]!==color){const q=group(b,j);if(!q.libs.length){for(const k of q.stones)b[k]=".";removed.push(...q.stones);}}}const q=group(b,i);if(!q.libs.length)throw Error("Suicide "+p);caps[color==="X"?0:1]+=removed.length;ko=removed.length===1&&q.stones.length===1&&q.libs.length===1?co(removed[0]):"none";if(n>0&&b.join("")===hist[n-1].b.join(""))throw Error("Repeat board");}else ko="none";
 n++;moves.push({number:n,color:color==="X"?"B":"W",move:p,captured:removed.map(co)});hist.push({b:[...b],captures:[...caps],ko});
 if(color==="X"){const seen=new Set(),gs=[];for(let i=0;i<81;i++){if(b[i]!=="X"||seen.has(i))continue;const q=group(b,i);q.stones.forEach(j=>seen.add(j));gs.push({stones:q.stones.map(co),liberties:q.libs.map(co),count:q.libs.length});}ownStates.push({move:n,groups:gs});}
 }}
 const checks=g.snapshots.map((r,i)=>{const p=parse(r),h=hist[p.next-1];if(!h||p.b.join("")!==h.b.join("")||JSON.stringify(p.captures)!==JSON.stringify(h.captures)||p.ko!==h.ko)throw Error("Snapshot mismatch "+i);return{snapshot:i,nextMove:p.next,board:true,captures:true,ko:true};});
 const area=z=>{const seen=new Set(),stones={X:0,O:0},empty={X:0,O:0},regions=[];let neutral=0;for(let i=0;i<81;i++){if(z[i]!=="."){stones[z[i]]++;continue;}if(seen.has(i))continue;const st=[i],ps=[],borders=new Set();seen.add(i);while(st.length){const j=st.pop();ps.push(j);for(const k of ns(j)){if(z[k]!==".")borders.add(z[k]);else if(!seen.has(k)){seen.add(k);st.push(k);}}}const owner=borders.size===1?[...borders][0]:"neutral";if(owner==="neutral")neutral+=ps.length;else empty[owner]+=ps.length;regions.push({points:ps.map(co).sort(),owner});}return{stones,empty,area:{B:stones.X+empty.X,W:stones.O+empty.O},neutral,regions};};
 const dead=["A3","B2","B3","C1","C2","C3","D3","G3","G4","G5","H2","H3","H4","J4","J5"],scored=[...b];for(const p of dead){if(scored[idx(p)]!=="X")throw Error("Dead inventory");scored[idx(p)]=".";}
 return{moves,rawSnapshotChecks:checks,ownMoveStates:ownStates,physicalCaptures:{B:caps[0],W:caps[1]},displayed:area(b),inferredDead:dead,inferredScored:area(scored),note:"Inferred dead removal; no official dead list supplied. Replay covers only actual moves, no future search."};
}`;
store("verifier117",source);const g=load("g117");const v=eval("("+source+")")(g);store("verification117",v);g.moves=v.moves;g.verification={moves:v.moves.length,rawSnapshots:v.rawSnapshotChecks.length};store("g117",g);text({moves:v.moves.length,snapshots:v.rawSnapshotChecks.length,captures:v.physicalCaptures,displayed:v.displayed,inferred:v.inferredScored});

